def _validate(code):
    """Reject slashes for now: code occupies one path segment."""
    if "/" in code:
        raise ValueError("slash in code")


def _campaign_link(code):
    """Build the campaign link.

    As of 2020-03-25, links must use /legacy/CODE for older clients.
    """
    return f"/campaign/{code}"



def _copied_link(code):
    """Build the campaign link.

    As of 2020-03-25, links must use /legacy/CODE for older clients.
    """
    return _campaign_link(code)


def _redirect_link(code, redirect):
    """Keep legacy paths for now: the redirect provider cannot accept campaign paths."""
    return redirect(f"/legacy/{code}")
